{
  "findings": [
    {
      "title": "Inconsistent definition of Full Analysis Set (FAS) and Measurable Disease Analysis Set (MDAS) with inclusion criteria",
      "page": 13,
      "quote": "The primary analysis population will be the Full Analysis Set (FAS), all patients receiving at least one dose of study treatment. ... Measurable Disease Analysis Set (MDAS) All patients who received at least 1 dose of study treatment, and who have Investigator-assessed measurable disease at baseline according to RECIST v1.1. The MDAS will only be used for the 8-patient interim futility evaluation within each tumor type. All patients will have Investigator-assessed measurable disease at baseline according to inclusion criteria.",
      "severity": "major"
    },
    {
      "title": "Inconsistent timing of interim futility evaluation: 12 weeks vs 32 weeks follow-up",
      "page": 14,
      "quote": "An interim futility evaluation will be performed within each tumor type after 8 treated patients with Investigator-assessed measurable disease at baseline (using the MDAS) have had 12 weeks of follow-up since first dose or have discontinued study drug.",
      "severity": "major"
    },
    {
      "title": "Inconsistent timing of interim efficacy analysis: '2 scheduled post-baseline scans' vs 6-month follow-up",
      "page": 15,
      "quote": "Interim efficacy analyses will also be performed (using the FAS) within an individual tumor type when enrolment to the tumor type has been closed, and all treated patients have had the opportunity to complete 2 scheduled post-baseline RECIST v1.1 scans.",
      "severity": "major"
    },
    {
      "title": "Inconsistent ORR CI for N=20, 40% response",
      "page": 15,
      "quote": "For a tumor type with N = 20, an ORR of 40% would have 95% CI (19.1%, 63.9%)",
      "severity": "major"
    },
    {
      "title": "Inconsistent window for tumor assessments in Table 6",
      "page": 20,
      "quote": "Tumor assessments (RECIST v1.1) m X CT or MRI scans performed q6w (± 1w)",
      "severity": "minor"
    },
    {
      "title": "Inconsistent window for follow-up visits in Table 7",
      "page": 24,
      "quote": "Window + 7 days ± 14 days",
      "severity": "minor"
    },
    {
      "title": "Inconsistent pregnancy test timing: 'within 72 hours before treatment assignment' vs 'prior to each administration'",
      "page": 22,
      "quote": "Within 72 hours before treatment assignment for all female patients of childbearing potential; a positive urine pregnancy test result must immediately be confirmed using a serum test. Perform repeat pregnancy tests (urine or serum test per institutional guideline) assignment, within 72 hours before infusion of each cycle and at end of treatment.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent ECG timing: 'within 3 days before administration' vs 'every fourth cycle'",
      "page": 22,
      "quote": "g Within 3 days before administration of IP. ECGs will be taken at every fourth cycle.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent ECHO/MUGA timing: 'before IP administration on Day 1 of Cycle 5' vs 'every 4 cycles'",
      "page": 23,
      "quote": "ECHO or MUGA scan assessments (note: the same test must be used for the patient throughout the study) will be performed at Screening and before IP administration on Day 1 of Cycle 5 and then every 4 cycles (± 7 days) (eg, Cycle 5, 9, 13), and at EOT.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent safety follow-up duration: '40 +7 days' vs '40 days'",
      "page": 23,
      "quote": "All adverse events AEs and SAEs (other than ILD/pneumonitis) will be collected from the time of signature of the ICF throughout the treatment period and including the safety follow-up (which is 40 +7 days after the discontinuation of all IPs).",
      "severity": "minor"
    },
    {
      "title": "Inconsistent PK sampling: 'pre-dose' and 'post-dose' on C1D1 but no timepoints specified",
      "page": 20,
      "quote": "Pre-dose blood sample for T-DXd PK (serum) (T-DXd, total anti-HER2 antibody, and MAAA-1181) X X X (C4 only) 8.5.1 Post-dose blood sample for T-DXd PK (serum) (T-DXd, total anti-HER2 antibody & MAAA-1181) X X X (C4 only) X 8.5.1",
      "severity": "minor"
    },
    {
      "title": "Inconsistent ADA sampling: 'within 8 hours before administration' vs 'Day 1 of Cycle 1, 2 and 4'",
      "page": 22,
      "quote": "j Within 8 hours before administration on Day 1 of Cycle 1, 2 and 4, and then every 4 cycles.",
      "severity": "minor"
    }
  ]
}
